{
  "IP": "neorv32_sdi",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "SDI operational enable",
      "Unit": "neorv32_sdi",
      "Information": "The operational enable setting determines whether the SDI interface is active and whether its transmit and receive FIFOs are retained. Bus software depends on it to enable or disable serial transfers.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: a bus write changes the stored enable at line 133, so an unauthorized write can alter interface operation. Availability: disabling the setting clears both FIFOs at lines 200 and 239 and controls the serial state at line 296, which can block transfers.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could write the control register to clear the enable and discard queued data, preventing SDI transfers.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        133
      ],
      "Held Lines": [
        133
      ],
      "Exit Lines": [
        143
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Interrupt configuration",
      "Unit": "neorv32_sdi",
      "Information": "These settings select which receive and transmit FIFO conditions generate an interrupt. The host depends on them to receive interrupt notifications for available, half-full, full, empty, and near-half-empty conditions.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: bus writes update the interrupt-enable settings at lines 135 through 139, changing which events are reported. Availability: those settings gate the interrupt output computation at lines 249 through 254, so changing them can suppress required notifications.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could rewrite the interrupt settings to suppress notifications and leave queued receive or transmit data unserviced.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        135,
        136,
        137,
        138,
        139
      ],
      "Held Lines": [
        135,
        136,
        137,
        138,
        139
      ],
      "Exit Lines": [
        147,
        148,
        149,
        150,
        151
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Transmit serial payload data",
      "Unit": "neorv32_sdi",
      "Information": "Transmit payload bytes written through the bus are queued and shifted onto the SDI data output. The serial peer depends on this information for outbound data transfers.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality: a bus-written byte is loaded into serial storage at line 305 and exposed on the external sdi_dat_o port at line 345. Integrity: bus data enters the transmit FIFO at line 201 and the serial register is loaded and shifted at lines 305 and 327, so an unauthorized write or alteration can change the transmitted payload.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could read or observe the serial output to disclose a queued byte, or write a replacement byte through the bus to corrupt the outbound transfer.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "sdi_dat_o"
      ],
      "Entry Lines": [
        201
      ],
      "Held Lines": [
        305,
        327
      ],
      "Exit Lines": [
        345
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "Receive serial payload data",
      "Unit": "neorv32_sdi",
      "Information": "Bytes received from the SDI data input are assembled and queued for host reads. The host depends on this information as the inbound serial payload.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Confidentiality: received bits are shifted into serial storage at line 327 and returned through bus_rsp_o.data at line 162. Integrity: the serial engine and receive FIFO store and transform the received bits at lines 327 and 235, so internal corruption or overwrite can change the returned payload.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could read the receive-data response to disclose an inbound byte or interfere with the stored byte before software retrieves it.",
      "Enters Through": [
        "sdi_dat_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        270
      ],
      "Held Lines": [
        327
      ],
      "Exit Lines": [
        162
      ]
    },
    {
      "Concept ID": "C5",
      "Concept Name": "Serial chip-select and transfer selection",
      "Unit": "neorv32_sdi",
      "Information": "The active-low SDI chip-select signal selects the interval in which a serial transfer starts and continues. The interface behavior and the reported chip-select status depend on this selection.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "no",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Availability: the synchronized selection starts a transfer at line 307 and terminates or prevents transfer progress at lines 315, 324, and 325, so the serial path can be blocked or ended prematurely.",
      "Objectives At Risk": [
        "A"
      ],
      "Attack": "An attacker could force the chip-select path inactive or cause premature deassertion so that required serial transfers never complete.",
      "Enters Through": [
        "sdi_csn_i"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        269
      ],
      "Held Lines": [
        275
      ],
      "Exit Lines": [
        160
      ]
    },
    {
      "Concept ID": "C6",
      "Concept Name": "FIFO event interrupt request",
      "Unit": "neorv32_sdi",
      "Information": "This internally generated event indicates that an enabled receive or transmit FIFO condition requires host attention. The integrating system depends on irq_o to service queued data and maintain interrupt-driven operation; it has no entry port because it is computed from local settings and FIFO events.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "Integrity: the logic at lines 249 through 254 determines the value of irq_o from enable settings and FIFO conditions, so an alteration can create false or missing interrupt requests. Availability: the same gated assignment can withhold irq_o, preventing the host from servicing a required FIFO event.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could alter the interrupt-generation conditions to raise spurious requests or suppress the request that causes the host to service queued data.",
      "Enters Through": [],
      "Leaves Through": [
        "irq_o"
      ],
      "Entry Lines": [],
      "Held Lines": [
        249
      ],
      "Exit Lines": [
        249
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Bus access command fields",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The strobe, direction, and register-select address are access command fields covered by the access-command rule rather than independent information pieces; they only select the accesses at lines 130 through 142."
    },
    {
      "Candidate Name": "Transmit FIFO buffered copy",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C3",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Receive FIFO buffered copy",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C4",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "FIFO fill and space status",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The FIFO availability, half-full, and free indicators only report or control movement of buffered data, so the buffer-status rule bars them as independent assets despite their readback at lines 153 through 158."
    },
    {
      "Candidate Name": "Serial synchronizer copies",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "C4",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Serial sequencing state and counter",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The state, bit counter, and start/done sequencing at lines 286 through 340 only order and pace serial transfers, so the sequencing-state rule bars them as separate information."
    },
    {
      "Candidate Name": "Serial start and done pulses",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The pulses at lines 292, 293, 308, and 329 only pace FIFO reads and writes and are covered by the pacing and sequencing rules."
    },
    {
      "Candidate Name": "Serial link clock",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The serial clock input and its synchronizer at lines 28 and 268 are a peer-device link clock, which the clock-line exclusion bars as a conceptual asset."
    },
    {
      "Candidate Name": "Clock and reset timing",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The unit clock and reset and their reset paths only time or initialize the design, and are excluded by the clock and reset rule at lines 23, 24, 115, 246, 263, and 283."
    },
    {
      "Candidate Name": "FIFO depth configuration",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "RTX_FIFO only fixes FIFO construction and depth through the generic at lines 20, 176, and 211, so it is a build-time value that cannot change at run time."
    },
    {
      "Candidate Name": "Bus response handshake and error",
      "Candidate Unit": "neorv32_sdi",
      "Merged Into": "",
      "Why Not Kept": "The response acknowledge repeats the request strobe and the error flag is tied to a constant at lines 125 and 126, so bus-handshake copies and constant error status are not independent information."
    }
  ],
  "Notes": []
}
